nodes.notes:
Called by WF-A, WF-B, WF-C with {op, payload}.

Operations:
- addSource    {type, mangaId, title}
- addQueue     {mangaId, chapterId, chapterNum, title}
- popNext      {}
- markPosted   {chapterId, mangaId, igMediaId, videoUrl}
- isPosted     {chapterId}
- list         {}
- removeSource {mangaId}

parameters.jsCode:
// QueueState dispatcher - owns the global queue/sources/posted state
// Input:  { op, payload }
// Output: { ok, ...result }

const data = $getWorkflowStaticData('global');
if (!data.sources) data.sources = [];
if (!data.queue) data.queue = [];
if (!data.posted) data.posted = [];

const input = $input.first().json;
const op = input.op;
const payload = input.payload || {};

const uuid = () => 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, c => {
  const r = Math.random() * 16 | 0;
  return (c === 'x' ? r : (r & 0x3 | 0x8)).toString(16);
});

const now = () => new Date().toISOString();

let result;
switch (op) {
  case 'addSource': {
    if (!payload.mangaId) { result = { ok: false, error: 'mangaId required' }; break; }
    const existingSource = data.sources.find(s => s.mangaId === payload.mangaId);
    if (existingSource) {
      if ((!existingSource.title || existingSource.title.trim() === '') && payload.title) {
        existingSource.title = payload.title;
      }
      result = { ok: false, error: 'source already exists', source: existingSource, totalSources: data.sources.length };
      break;
    }
    const entry = {
      id: uuid(),
      type: payload.type || 'mangadex',
      mangaId: payload.mangaId,
      title: payload.title || '',
      addedAt: now()
    };
    data.sources.push(entry);
    result = { ok: true, source: entry, totalSources: data.sources.length };
    break;
  }

  case 'addQueue': {
    if (!payload.mangaId || !payload.chapterId) {
      result = { ok: false, error: 'mangaId and chapterId required' };
      break;
    }
    if (data.posted.some(p => p.chapterId === payload.chapterId)) {
      result = { ok: false, error: 'chapter already posted', chapterId: payload.chapterId };
      break;
    }
    if (data.queue.some(q => q.chapterId === payload.chapterId)) {
      result = { ok: false, error: 'chapter already queued', chapterId: payload.chapterId };
      break;
    }
    const entry = {
      id: uuid(),
      mangaId: payload.mangaId,
      chapterId: payload.chapterId,
      chapterNum: payload.chapterNum ?? null,
      title: payload.title || '',
      addedAt: now()
    };
    data.queue.push(entry);
    result = { ok: true, queued: entry, queueLength: data.queue.length };
    break;
  }

  case 'popNext': {
    if (data.queue.length === 0) { result = { ok: false, empty: true }; break; }
    const next = data.queue.shift();
    result = { ok: true, next, remaining: data.queue.length };
    break;
  }

  case 'markPosted': {
    if (!payload.chapterId) { result = { ok: false, error: 'chapterId required' }; break; }
    const entry = {
      chapterId: payload.chapterId,
      mangaId: payload.mangaId || '',
      postedAt: now(),
      igMediaId: payload.igMediaId || null,
      videoUrl: payload.videoUrl || null
    };
    data.posted.push(entry);
    data.queue = data.queue.filter(q => q.chapterId !== payload.chapterId);
    result = { ok: true, posted: entry, totalPosted: data.posted.length };
    break;
  }

  case 'isPosted': {
    if (!payload.chapterId) { result = { ok: false, error: 'chapterId required' }; break; }
    result = { ok: true, isPosted: data.posted.some(p => p.chapterId === payload.chapterId) };
    break;
  }

  case 'list': {
    result = {
      ok: true,
      sources: data.sources,
      queue: data.queue,
      posted: data.posted.slice(-50),
      counts: {
        sources: data.sources.length,
        queue: data.queue.length,
        posted: data.posted.length
      }
    };
    break;
  }

  case 'removeSource': {
    if (!payload.mangaId) { result = { ok: false, error: 'mangaId required' }; break; }
    const before = data.sources.length;
    data.sources = data.sources.filter(s => s.mangaId !== payload.mangaId);
    result = { ok: true, removed: before - data.sources.length };
    break;
  }

  default:
    result = {
      ok: false,
      error: `unknown op: ${op}`,
      validOps: ['addSource', 'addQueue', 'popNext', 'markPosted', 'isPosted', 'list', 'removeSource']
    };
}

return [{ json: result }];

